 * grammar needs where it expects a keyword — `upper(x)` calls a function and
 * `` `upper`(x) `` is not something GQL writes.
 *
 * @example A word is one whether or not GQL reserves it
 *     \App\Gql\Parsing\TokenReader::of('upper(x)')->atWord() // => true
 * @example A name in back quotes is not a word
 *     \App\Gql\Parsing\TokenReader::of('`upper`(x)')->atWord() // => false
 *
 * @return bool True when it does
 */
public function atWord(): bool
{
    return $this->current()->kind === TokenKind::Name;
}

/**
 * Reports whether the reading stands at a name GQL would let a query bind.
 *
 * A variable is the one place GQL writes `<regular identifier>` and nothing else,
 * so a reserved word is not one and neither is a name in back quotes. Both answer
 * false here, which is what lets a pattern tell `(n:Method)` from `(:Method)` and
 * `(n WHERE ...)` from the clause that follows a pattern.
 *
 * @example A plain name could be bound
 *     \App\Gql\Parsing\TokenReader::of('p.firstName')->atVariable() // => true
 * @example A word GQL reserves could not
 *     \App\Gql\Parsing\TokenReader::of('WHERE p.line > 1')->atVariable() // => false
 *
 * @return bool True when it does
 */
public function atVariable(): bool
{
    $token = $this->current();

    return $token->kind === TokenKind::Name && !ReservedWords::reserves($token->value);
}

/**
 * Moves past a name, reporting the query wrong if there is not one here.
 *
 * This is the keyword position: a word the grammar knows, such as the name of a
 * function being called. A name is taken here whatever it spells, because what it
 * may spell is settled by the grammar rather than by GQL's reserved words.
 *
 * @example A required name is taken
 *     \App\Gql\Parsing\TokenReader::of('firstName')->expectName() // => 'firstName'
 * @example A word GQL reserves is one, since a function is called by a keyword
 *     \App\Gql\Parsing\TokenReader::of('upper(x)')->expectName() // => 'upper'
 *
 * @return string The name, as it stands for itself
 *
 * @throws GqlException If the query does not have one here
 */
public function expectName(): string
{
    if (!$this->atName()) {
        $this->fail('a name');
    }

    return $this->take()->value;
}

/**
 * Moves past an identifier: a label, a property, a field or an alias.
 *
 * GQL writes each of those `<identifier>`, which is a name it does not reserve or
 * any name at all in back quotes. So a graph with a label called `Function` is
 * matched by `` (:`Function`) ``, and `(:Function)` is a query that was written
 * wrong — `FUNCTION` is a word the standard holds back for a later edition.
 *
 * @example A name GQL does not reserve is an identifier
 *     \App\Gql\Parsing\TokenReader::of('firstName')->expectIdentifier() // => 'firstName'
 * @example A word GQL reserves is one when it is written in back quotes
 *     \App\Gql\Parsing\TokenReader::of('`value`')->expectIdentifier() // => 'value'
 * @example And is not one when it is not
 *     \App\Gql\Parsing\TokenReader::of('value')->expectIdentifier() // throws \App\Gql\GqlException: reserves
 *
 * @return string The identifier, as it stands for itself
 *
 * @throws GqlException If the query does not have one here
 */
public function expectIdentifier(): string
{
    if (!$this->atName()) {
        $this->fail('a name');
    }
    $token = $this->current();
    if ($token->kind === TokenKind::Name && ReservedWords::reserves($token->value)) {
        $this->refuseReserved($token, 'write it in back quotes to use it as a name');
    }

    return $this->take()->value;
}

/**
 * Moves past the name a query binds something to.
 *
 * GQL writes a binding variable `<regular identifier>`, which is narrower than an
 * identifier in both directions: a reserved word is not one, and neither is a name
 * in back quotes. A variable is therefore always a word a reader can read.
 *
 * @example A name GQL does not reserve can be bound
 *     \App\Gql\Parsing\TokenReader::of('person')->expectVariable() // => 'person'
 * @example A word GQL reserves cannot, back quotes or not
 *     \App\Gql\Parsing\TokenReader::of('`value`')->expectVariable() // throws \App\Gql\GqlException: syntax error
 *
 * @return string The variable's name
 *
 * @throws GqlException If the query does not have one here
 */
public function expectVariable(): string
{
    $token = $this->current();
    if ($token->kind === TokenKind::Name && ReservedWords::reserves($token->value)) {
        $this->refuseReserved($token, 'a query binds a name to a word GQL leaves free');
    }
    if (!$this->atVariable()) {
        $this->fail('a name');
    }

    return $this->take()->value;
}

/**
 * Reports that a word GQL reserves was written where a name was wanted.
 *
 * @example A reserved word is refused by name, and told what to write instead
 *     $reader = \App\Gql\Parsing\TokenReader::of('value');
 *     $reader->refuseReserved($reader->current(), 'write it in back quotes') // throws \App\Gql\GqlException: GQL reserves "VALUE"
 *
 * @param Token  $token  The word, and where it stands
 * @param string $remedy What the reader can write instead
 *
 * @throws GqlException Always
 */
public function refuseReserved(Token $token, string $remedy): never
{
    throw GqlException::syntax(
        'GQL reserves "'.strtoupper($token->value).'", so it is not a name here: '.$remedy,
        $token->line,
        $token->column,
        $token->describe(),
    );
}

